if GetLocale() ~= "koKR" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.mage.fire.Name"] = "불"
L["rm.era.mage.fire.Description"] = "10레벨부터 60레벨까지의 화염 로테이션으로, 화염에 특성 점수가 있고 냉기에는 없거나 화염이 주 특성 트리일 때 선택됩니다. 불덩이 작열(없으면 화염구)로 시작; 냉정 후 불덩이 작열; 불태우기 연마가 있으면 오래 살아남을 대상에게 불태우기로 화염 저항력 약화 5중첩 유지; 마무리는 화염 작렬과 불태우기; 빈틈은 화염구. 교전 중인 적이 셋 이상이면: 화염 폭풍, 불기둥, 신비한 폭발, 냉기 돌풍, 눈보라. 알림: 정예와 긴 전투에서 불태우기 5중첩일 때 발화, 갑옷, 신비한 지능, 마나석, 얼음 보호막, 마나 보호막, 환기, 마법 차단, 하급 저주 해제, 얼음 방패, 냉정. 기본적으로 꺼져 있음: 준비될 때마다 화염 작렬 끼워 넣기."
L["rm.era.mage.fire.warcrafttavern.Name"] = "화염 (Warcraft Tavern)"
L["rm.era.mage.fire.warcrafttavern.Description"] = "Warcraft Tavern을 따른 화염 로테이션으로, 추천 화염 기본 제공 로테이션의 대안이며 기본적으로 꺼져 있습니다: 이것을 켜고 그것을 끄거나, 이것의 우선순위를 높이세요. 발화는 불태우기 중첩을 기다리지 않고 정예와 우두머리 전투 시작 시 사용; 불덩이 작열로 시작; 불태우기 연마가 있으면 불태우기로 5중첩 유지; 빈틈은 화염구; 화염 작렬은 이동 중에만. 무리: 먼저 불기둥, 그다음 가까이에서는 신비한 폭발, 냉기 돌풍, 화염 폭풍, 원거리에서는 눈보라. 알림은 화염 기본 제공 로테이션과 같습니다."
L["rm.era.mage.frost.Name"] = "냉기"
L["rm.era.mage.frost.Description"] = "1레벨부터 60레벨까지의 냉기 로테이션이며, 비전 빌드에도 쓰이고 특성을 찍기 전 마법사의 기본값입니다. 얼음 화살(4레벨 전에는 화염구); 몹이 내게 다가오면 얼음 회오리(공격대 우두머리 제외); 신비한 화살 연마가 있으면 몹이 다가온 뒤 신비한 화살; 적이 셋 이상 교전 중이면 냉기 돌풍, 신비한 폭발, 눈보라; 마나가 넉넉하면 이동 중 화염 작렬; 혼자일 때 일반 몹은 화염 작렬과 마법봉으로 마무리; 마나가 떨어지면 마법봉. 알림: 갑옷(혼자일 때 얼음 갑옷, 그룹에서는 마법사 갑옷, 직접 고른 갑옷은 바꾸지 않음), 신비한 지능, 마나석 창조와 사용, 얼음 보호막, 마나 보호막, 환기, 마법 차단, 하급 저주 해제, 얼음 방패, 한파, 신비의 마법 강화와 냉정. 기본적으로 꺼져 있음: 산산조각 불기둥과 혹한의 추위를 쌓기 위한 1등급 얼음 화살. 점멸, 변이, 카이팅, 대상 선택은 직접 판단합니다."
L["rm.era.mage.frost.icyveins.Name"] = "냉기 광역 사냥 (Icy Veins)"
L["rm.era.mage.frost.icyveins.Description"] = "Icy Veins의 광역 사냥 공략을 따른 눈보라 레벨업으로, 눈보라 연마를 찍고 혼자 플레이할 때 자동으로 선택됩니다. 교전 중인 적이 둘 이상이면: 무리에 얼음 회오리, 얼음 회오리가 재사용 대기 중일 때 냉기 돌풍, 옆에 아무도 없으면 눈보라, 옆에 있으면 신비한 폭발; 단일 대상에게는 얼음 화살, 마무리는 화염 작렬과 마법봉. 매 전투 전에 마나 보호막과 얼음 보호막을 겁니다. 무리 모으기, 점멸, 카이팅은 직접 판단합니다."
L["rm.forever.mage.arcane.Name"] = "비전"
L["rm.forever.mage.arcane.Description"] = "비전이 주 특성 트리이고 11포인트를 투자했으며 비전 작렬을 배웠을 때의 비전 로테이션입니다. 혼자일 때는 얼음 화살로, 그룹에서는 비전 작렬로 끌어온 뒤, 화살 탄막 발동 시 신비한 화살, 번뜩임 발동 시 비전 작렬, 비전 작렬 3중첩에서 비전 격노, 쓸 수 있는 동안(Forever에서는 마나가 숨겨져 있음) 정예에게는 4중첩까지, 다른 대상에게는 2중첩까지 비전 작렬을 쌓고, 그다음 화살 탄막을 노리며 냉기화염 화살, 얼음 화살 또는 화염구를 사용하고, 혼자이고 주문을 쓸 마나가 없으면 마법봉을 사용합니다. 비전 격노가 없으면(이전 베타 설계) 화염 작렬로 중첩을 소모합니다. 이동 중: 화염 작렬. 셋 이상의 적과 싸우면: 신비한 폭발. 알림: 정예 상대 냉정과 신비의 마법 강화(신비의 마법 강화는 더 이상 마나가 절반이 되기를 기다리지 않음), 그리고 마법사 유지 관리 알림."
L["rm.forever.mage.fire.Name"] = "불"
L["rm.forever.mage.fire.Description"] = "화염이 주 특성 트리이고 11포인트(불덩이 작렬 계층)를 투자한 뒤의 화염 로테이션입니다. 정예에게는 불덩이 작렬로, 그 외에는 냉기화염 화살 또는 화염구로 끌어온 뒤, 열기 3중첩에서 불덩이 작렬, 서리의 손가락 발동이나 얼어붙은 대상에게 얼음창(화염/냉기 하이브리드), 재사용 대기시간마다 화염 작렬, 정예에게 화염 저항력 약화 5중첩을 유지하는 불태우기, 냉기화염 화살(40레벨부터) 또는 화염구, 혼자이고 주문을 쓸 마나가 없으면 마법봉을 사용합니다. 이동 중: 화염 작렬 또는 얼음창. 넷 이상의 적과 싸우면: 불기둥, 화염 폭풍, 신비한 폭발. 불태우기는 불태우기 연마를 배운 뒤에만 중첩을 시작하며, 근거리 불태우기는 직접 켜기 전까지 꺼져 있습니다. 알림: 정예 상대 발화와 냉정, 그리고 마법사 유지 관리 알림."
L["rm.forever.mage.fire.icyveins.Name"] = "화염 레벨업 (Icy Veins)"
L["rm.forever.mage.fire.icyveins.Description"] = "불태우기 연마 없이 하는 Icy Veins의 화염 레벨업 빌드로, 추천 화염 기본 제공 로테이션의 대안이며 기본적으로 꺼져 있습니다: 이것을 켜고 그것을 끄거나, 이것의 우선순위를 높이세요. 불덩이 작렬로 끌어오고, 불꽃의 잔흔을 소모할 때 화염 작렬, 몹이 다가올 때 불태우기(Forever에서는 대상의 생명력이 숨겨져 있으므로 생명력이 낮은 대상 마무리는 직접 판단합니다), 그다음 냉기화염 화살(40레벨부터) 또는 화염구를 사용합니다. 광역, 이동, 마법봉, 알림은 화염 기본 제공 로테이션과 같지만 발화와 냉정은 없습니다."
L["rm.forever.mage.frost.Name"] = "냉기"
L["rm.forever.mage.frost.Description"] = "1레벨부터 60레벨까지의 냉기 로테이션이며, 특성 주문을 배우기 전 Forever 마법사의 기본값입니다(4레벨에 얼음 화살을 배우기 전까지는 화염구). 얼음 화살로 끌어온 뒤, 서리의 손가락 발동이나 얼어붙은 대상에게 얼음창(얼음 화살을 시전 중일 때도, 취소하거나 함께 보내기 위해), 혹한의 추위 5중첩에서 냉기 돌풍, 화살 탄막 발동 시 신비한 화살, 얼음 화살, 혼자이고 얼음 화살을 쓸 마나가 없으면 마법봉을 사용합니다. 이동 중: 얼음창, 없으면 화염 작렬. 셋 이상의 적과 싸우면: 냉기 돌풍, 다섯 이상이면: 눈보라, 몹이 나를 공격하면 신비한 폭발. Warcraft Tavern의 불기둥과 신비한 폭발 광역 공격도 포함되어 있지만 꺼져 있습니다. 알림: 신비한 지능, 갑옷(혼자일 때 얼음 갑옷 또는 냉기 갑옷, 그룹에서 마법사 갑옷, 직접 고른 갑옷은 바꾸지 않음), 얼음 보호막, 마법 차단, 하급 저주 해제, 몹이 다가오면 얼음 회오리, 한파. Forever에서는 생명력과 마나가 애드온에 숨겨져 있으므로 화염 작렬로 생명력이 낮은 대상 마무리, 환기, 얼음 방패는 직접 판단합니다. 점멸, 카이팅, 변이, 마나 보석도 직접 판단합니다."
L["rm.mop.mage.arcane.Name"] = "추천"
L["rm.mop.mage.arcane.Description"] = "10레벨부터 90레벨까지 비전에게 권장합니다(비전 전문화에서 선택). 비전 작렬로 비전 충전물 4개를 쌓습니다. 4개일 때 신비한 화살! 발동이 있으면 신비한 화살로 소모하고, 없으면 마나가 90% 미만으로 떨어지는 대로 비전 탄막을 사용합니다. 마나가 95%를 넘으면 계속 작렬을 쓰며, 시뮬레이터도 이렇게 플레이합니다. 신비한 화살 발동 2회를 쌓아 두지 않고, 시간 돌리기가 되돌아가기 전에 탄막을 시전하며, 적이 둘 이상이면 충전물 4개마다 탄막을 사용합니다. 가까이 다섯이 있으면 냉기 돌풍과 신비한 폭발. 특성으로 배운 폭탄 주문을 유지하고, 빙하 없이 이동 중에는 화염 작렬이나 얼음창을 사용합니다. 알림: 충전물 4개와 발동이 있을 때 신비의 마법 강화와 시간 돌리기, 냉기 갑옷(54레벨 전에는 타오르는 갑옷), 신비한 총명함, 마법 차단, 마나석, 환영 복제, 얼음 보호막, 빙하, 마력의 룬 또는 마법의 기원. 시간 왜곡, 마법 훔치기, 냉정은 꺼져 있으며, 마력의 룬은 여전히 직접 배치해야 합니다."
L["rm.mop.mage.arcane.icyveins.Name"] = "충전물 4개에서 탄막 (Icy Veins)"
L["rm.mop.mage.arcane.icyveins.Description"] = "공략(Icy Veins, Wowhead, Method, wowtbc.gg)의 비전 규칙으로, 권장 비전 기본 제공 로테이션의 대안입니다: 비전 충전물 4개에서 발동이 있으면 신비한 화살, 그 외에는 마나와 관계없이 비전 탄막을 사용하며, 신비한 화살은 충전물 4개에서만 사용합니다. 그 밖의 모든 것(시간 돌리기, 폭탄 주문, 광역, 이동, 알림)은 권장 로테이션과 같지만, 신비의 마법 강화는 발동을 기다리지 않고 충전물 4개에서 제안합니다. 기본적으로 꺼져 있습니다: 이것을 켜고 권장 비전 기본 제공 로테이션을 끄거나, 이것의 우선순위를 높이세요."
L["rm.mop.mage.fire.Name"] = "추천"
L["rm.mop.mage.fire.Description"] = "10레벨부터 90레벨까지 화염에게 권장합니다(화염 전문화에서 선택). 일반 시전 불덩이 작렬로 시작한 뒤, 지옥불 작렬(24레벨 전에는 화염 작렬)로 열기를 불덩이 작렬! 발동으로 바꾸고, 발화의 재사용 대기시간이 곧 끝나는 경우가 아니면 즉시 시전합니다. 그다음 화염구를 시전하면서 다음 열기를 기다립니다. 발화는 대상에 작열과 불덩이 작렬 화상이 있는 동안 불덩이 작렬 직후에 사용합니다. 애드온은 작열이 얼마나 큰지 볼 수 없으므로, 약한 작열은 직접 판단하세요. 특성으로 배운 폭탄 주문을 유지하고, 적이 둘 이상 나와 싸우면 지옥불 작렬로 퍼뜨리며, 가까이 다섯이 있으면 냉기 돌풍과 신비한 폭발, 이동 중에는 불태우기를 사용합니다. 알림: 타오르는 갑옷, 냉정, 두 발동이 모두 있을 때 시간 돌리기, 마나석, 신비한 총명함, 마법 차단, 환영 복제, 얼음 보호막, 빙하, 마법의 기원 또는 마력의 룬. 용의 숨결, 시간 왜곡, 마법 훔치기는 꺼져 있습니다."
L["rm.mop.mage.fire.icyveins.Name"] = "불덩이 작렬! 보류 (Icy Veins)"
L["rm.mop.mage.fire.icyveins.Description"] = "Icy Veins, Method, wowtbc.gg의 화염 플레이로, 권장 화염 기본 제공 로테이션의 대안입니다: 불덩이 작렬! 발동은 열기가 함께할 때까지 보류했다가 화염구와 함께 시전하며, 곧 만료될 때만 단독으로 소모합니다. 그 밖의 모든 것은 권장 로테이션과 같습니다. 기본적으로 꺼져 있습니다: 이것을 켜고 권장 화염 기본 제공 로테이션을 끄거나, 이것의 우선순위를 높이세요."
L["rm.mop.mage.frost.Name"] = "추천"
L["rm.mop.mage.frost.Description"] = "10레벨부터 90레벨까지의 냉기 로테이션입니다(냉기 전문화에서 선택). 서리의 손가락 2회에서 얼음창, 두뇌 빙결 시 얼음불꽃 화살, 특성으로 배운 폭탄 주문, 얼어붙은 구슬, 서리의 손가락 1회에서 얼음창, 얼음 화살; 87레벨부터는 시간 돌리기가 10초 미만 남았으면 발동을 보류합니다. 적이 둘 이상이면: 얼어붙은 구슬, 가까이 있으면 냉기 돌풍과 신비한 폭발, 넷이 가만히 서 있으면 눈보라. 빙하 없이 이동 중에는 얼음창과 화염 작렬. 알림: 물의 정령, 우두머리가 아닌 대상에게 얼리기(직접 배치), 시간 돌리기에 맞춘 얼음 핏줄, 얼음 핏줄 중 서리의 손가락 2회에서 시간 돌리기, 냉기 갑옷(54레벨 전에는 타오르는 갑옷), 마나석, 신비한 총명함, 마법 차단, 환영 복제, 얼음 보호막, 빙하, 마법의 기원 또는 마력의 룬. 매서운 한파, 냉정, 시간 왜곡, 마법 훔치기는 꺼져 있습니다."
L["rm.mop.mage.unspecialized.Name"] = "전문화 선택 전"
L["rm.mop.mage.unspecialized.Description"] = "1–9레벨과 아직 전문화를 고르지 않은 마법사용입니다. 얼음불꽃 화살, 대상 마무리나 이동 중에는 화염 작렬, 배운 뒤에는 이동 중 얼음창, 근접 거리에 적이 셋 이상이면 신비한 폭발. 알림: 몹이 다가오면 얼음 회오리, 마법 차단, 해당 레벨에 도달하면 타오르는 갑옷과 신비한 총명함. 10레벨에 전문화를 고르면 그 전문화의 기본 제공 로테이션으로 바뀝니다."
L["rm.retail.mage.arcane.Name"] = "Blizzard 전투 보조"
L["rm.retail.mage.arcane.Description"] = "비전 전문화에 권장됩니다. Blizzard의 전투 보조가 다음으로 제안하는 주문을 강조합니다. 한밤 전투에서 게임이 애드온에 아직 읽기를 허용하는 유일한 로테이션 조언이며, 시전이나 정신 집중 중에는 기다립니다. 이와 함께 전투 보조가 플레이어에게 맡기는 것을 알려 줍니다: 전투 중 비전 쇄도, 전투 밖에서 신비한 지능, 차단 가능한 시전에 마법 차단, 전투 중 준비될 때마다 오색 방벽, 그리고 전투 중 종족 재사용 대기시간 기술. 적의 시전은 전투 중 숨겨지므로 마법 차단은 게임이 시전을 보여 주는 곳에서만 강조되며, Retail에서는 생명력이 숨겨지므로 얼음 방패 등 긴급 기술은 직접 판단합니다. 환영 복제, 시간 돌리기, 점멸, 장신구는 직접 판단합니다."
L["rm.retail.mage.arcane.guide.Name"] = "참고용 (Icy Veins와 SimulationCraft)"
L["rm.retail.mage.arcane.guide.Description"] = "참고용이며 기본적으로 꺼져 있습니다. 공략의 비전 우선순위입니다. 한밤 전투에서는 비전 연사와 번뜩임이 애드온에 숨겨지므로(비전 충전물만 보임) 그곳에서는 실행할 수 없으며, Retail에서는 마나가 숨겨지므로 마나가 낮을 때의 환기는 직접 판단합니다. 읽어 보거나, 복제해서 실험해 보세요. 비전 작렬로 끌어옵니다. 성난태양: 연사 12 미만일 때 번뜩임 발동 시 신비한 화살, 비전의 영혼 밖에서 오색 화살, 충전물 4개에 연사 12와 번뜩임이 있거나 연사 25이거나, 비전의 영혼 중이면 충전물 수와 관계없이 비전 탄막, 오색 화살, 충전물 3개 미만에서 비전 보주, 적이 셋이거나 충전물이 없으면 비전 파동, 비전 작렬. 주문술사(쇄편의 마술을 배운 경우): 오색 화살, 몹 무리에 보주, 연사 20에서 탄막(적이 둘 이상이면 충전물 4개일 때만), 연사 15 미만일 때 번뜩임 발동 시 신비한 화살, 충전물 3개 미만에서 보주와 파동(비전 쇄도 중에는 파동 없음), 비전 작렬. 비전 작렬을 시전할 수 없으면 비전 탄막. 알림: 비전 쇄도, 쇄도 중이거나 쇄도보다 훨씬 전에 탄막이나 오색 화살 뒤 비전의 여파, 탄막 뒤 충전물이 없을 때 냉정, 그리고 전투 보조 기본 제공 로테이션의 알림."
L["rm.retail.mage.fire.Name"] = "Blizzard 전투 보조"
L["rm.retail.mage.fire.Description"] = "화염 전문화에 권장됩니다. Blizzard의 전투 보조가 다음으로 제안하는 주문을 강조합니다. 한밤 전투에서 게임이 애드온에 아직 읽기를 허용하는 유일한 로테이션 조언이며, 시전이나 정신 집중 중에는 기다립니다. 이와 함께 전투 보조가 플레이어에게 맡기는 것을 알려 줍니다: 전투 중 발화, 전투 밖에서 신비한 지능, 차단 가능한 시전에 마법 차단, 전투 중 준비될 때마다 이글거리는 방벽, 그리고 전투 중 종족 재사용 대기시간 기술. 적의 시전은 전투 중 숨겨지므로 마법 차단은 게임이 시전을 보여 주는 곳에서만 강조되며, Retail에서는 생명력이 숨겨지므로 얼음 방패 등 긴급 기술은 직접 판단합니다."
L["rm.retail.mage.fire.guide.Name"] = "참고용 (Icy Veins, Wowhead와 SimulationCraft)"
L["rm.retail.mage.fire.guide.Description"] = "참고용이며 기본적으로 꺼져 있습니다. 공략의 화염 우선순위입니다. 한밤 전투에서는 몰아치는 열기, 열기, 화염 파열, 화염 작렬 충전이 숨겨지므로 그곳에서는 실행할 수 없습니다. 시전이 끝나 가는 동안 화염 작렬로 열기를 몰아치는 열기로 바꾸고, 불덩이 작렬로 끌어옵니다. 이상 고열 발동 시 불덩이 작렬(적이 넷 이상이면 불기둥), 유성, 몰아치는 열기 발동 시 불덩이 작렬, 발화 중 열기 발동 시 화염 작렬, 화염 파열 발동 시 불덩이 작렬, 일렁이는 열기 발동 시 또는 이동 중 불태우기, 열기 발동 시 화염 작렬, 그다음 얼음불꽃 화살 또는 화염구. 알림: 일반 시전이 끝날 때 발화, 이글거리는 방벽, 그리고 유틸리티 알림. 방화광을 기다리는 것과 유성을 발화에 맞추는 것은 직접 판단합니다."
L["rm.retail.mage.frost.Name"] = "Blizzard 전투 보조"
L["rm.retail.mage.frost.Description"] = "냉기 전문화에 권장됩니다. Blizzard의 전투 보조가 다음으로 제안하는 주문을 강조합니다. 한밤 전투에서 게임이 애드온에 아직 읽기를 허용하는 유일한 로테이션 조언이며, 시전이나 정신 집중 중에는 기다립니다. 이와 함께 전투 보조가 플레이어에게 맡기는 것을 알려 줍니다: 특성이 있고 정령이 없으면 물의 정령 소환, 전투 밖에서 신비한 지능, 차단 가능한 시전에 마법 차단, 전투 중 준비될 때마다 얼음 보호막, 그리고 전투 중 종족 재사용 대기시간 기술. 적의 시전은 전투 중 숨겨지므로 마법 차단은 게임이 시전을 보여 주는 곳에서만 강조되며, Retail에서는 생명력이 숨겨지므로 얼음 방패 등 긴급 기술은 직접 판단합니다."
L["rm.retail.mage.frost.guide.Name"] = "참고용 (Icy Veins와 SimulationCraft)"
L["rm.retail.mage.frost.guide.Description"] = "참고용이며 기본적으로 꺼져 있습니다. 영웅 특성 트리별 공략의 냉기 우선순위입니다. 한밤 전투에서는 발동 효과, 빙결 중첩, 재사용 대기시간이 숨겨지므로 그곳에서는 실행할 수 없습니다. 얼음불꽃 화살 또는 얼음 화살로 끌어옵니다. 서리불꽃(얼음불꽃 화살을 배운 경우): 준비되면 혹한의 쐐기, 적이 하나나 둘이면 혜성 폭풍, 열기 동공 없이 두뇌 빙결 발동 시 진눈깨비, 서리의 손가락 2중첩에서 얼음창, 서리 광선, 얼어붙은 구슬, 적이 셋일 때 빗발치는 냉기 발동 시 눈보라, 열기 동공이 있을 때 서리의 손가락 발동 시 또는 빙결 12중첩에서 얼음창, 진눈깨비, 적이 다섯이면 서리 회오리 또는 냉기 돌풍, 그다음 혹한의 쐐기 또는 얼음불꽃 화살. 주문술사: 혜성 폭풍, 두뇌 빙결 발동 시 진눈깨비, 서리의 손가락 2중첩에서 얼음창, 얼어붙은 구슬, 준비되면 혹한의 쐐기, 빗발치는 냉기 발동 시 눈보라, 서리의 손가락 발동 시 또는 빙결 6중첩에서 얼음창, 서리 광선, 진눈깨비, 적이 넷이면 서리 회오리 또는 냉기 돌풍, 일곱이면 눈보라, 그다음 혹한의 쐐기 또는 얼음 화살. 이동 중에는 얼음창. 알림: 물의 정령 소환, 얼음 보호막, 그리고 유틸리티 알림."
L["rm.retail.mage.initial.Name"] = "Blizzard 전투 보조"
L["rm.retail.mage.initial.Description"] = "전문화를 선택하기 전(게임이 마법사의 초기 전문화를 보고하는 동안)에 권장됩니다. Blizzard의 전투 보조가 다음으로 제안하는 주문을 강조합니다. 한밤 전투에서 게임이 애드온에 아직 읽기를 허용하는 유일한 로테이션 조언이며, 시전이나 정신 집중 중에는 기다립니다. 이와 함께 모든 마법사 기본 제공 로테이션이 공유하는 알림을, 해당 주문을 배운 뒤에 각각 제공합니다. 10레벨에 전문화를 선택하면 해당 전문화의 기본 제공 로테이션이 대신합니다."
L["rm.sod.mage.arcane.Name"] = "비전 (SoD)"
L["rm.sod.mage.arcane.Description"] = "디스커버리 시즌 비전 공격 로테이션으로, 비전이 주 특성 트리이고 비전 작렬을 새겼을 때 선택됩니다. 화살 탄막에 신비한 화살; 비전 작렬 4중첩에서 비전 탄막; 안전할 때 재앙불꽃 화살, 단 재앙불꽃 4중첩 이상에서는 절대 사용하지 않음; 재사용 대기시간마다 살아있는 불꽃; 빈틈은 비전 작렬. 이동 중에는 비전 탄막과 화염 작렬; 무리에는 살아있는 불꽃과 신비한 폭발. 알림: 정예와 긴 전투에서 신비의 마법 강화, 신비의 마법 강화와 함께 또는 이동 중에 냉정, 얼음 핏줄, 한파와 그 밖의 마법사 알림."
L["rm.sod.mage.fire.Name"] = "화염 (SoD)"
L["rm.sod.mage.fire.Description"] = "1레벨부터 60레벨까지의 디스커버리 시즌 화염 로테이션이며, 그곳에서 마법사의 기본값입니다. 새긴 룬을 사용합니다: 몰아치는 열기에 즉시 불덩이 작열; 오래 살아남을 대상에게 살아있는 폭탄 유지; 화염 저항력 약화가 2중첩 미만이거나 곧 사라지면 불태우기 연마와 함께 불태우기; 재사용 대기시간마다 살아있는 불꽃; 화염 저항력 약화 5중첩에서 재앙불꽃 화살, 단 재앙불꽃 4중첩 이상에서는 절대 사용하지 않음(5번째 중첩은 나를 죽입니다); 얼음불꽃 화살, 없으면 화염구. 이동 중에는 살아있는 폭탄, 살아있는 불꽃, 화염 작렬; 무리에는 살아있는 불꽃, 살아있는 폭탄, 화염 폭풍, 냉기 돌풍, 불기둥, 눈보라. 알림: 과열과 함께 화염 작렬, 발화, 얼음 핏줄과 한파, 타오르는 갑옷 또는 다른 갑옷, 신비한 지능, 마나석, 얼음 보호막, 마나 보호막, 환기, 마법 차단, 저주 해제, 얼음 방패. 여러 대상에 살아있는 폭탄을 퍼뜨리는 것은 직접 판단합니다."
L["rm.sod.mage.frost.Name"] = "냉기 (SoD)"
L["rm.sod.mage.frost.Description"] = "10레벨부터의 디스커버리 시즌 냉기 로테이션으로, 냉기가 주 특성 트리일 때 선택됩니다. 서리의 손가락은 내 빙하 작용이 3중첩 이상이면 얼음창에, 그 외에는 동결에 사용; 두뇌 빙결 발동 시, 그 외에는 안전할 때 재앙불꽃 화살, 단 재앙불꽃 4중첩 이상에서는 절대 사용하지 않음; 새겼다면 살아있는 폭탄과 살아있는 불꽃; 비전냉기 화살, 없으면 얼음불꽃 화살, 없으면 얼음 화살. 이동 중에는 얼음창, 얼어붙은 구슬, 살아있는 폭탄, 화염 작렬; 무리에는 얼어붙은 구슬, 살아있는 불꽃, 살아있는 폭탄, 눈보라, 냉기 돌풍. 알림: 얼어붙은 구슬, 얼음 핏줄, 한파, 갑옷, 마나석과 그 밖의 마법사 알림. 화살이 적중할 때 주문을 대기열에 넣는 것은 직접 판단합니다."
L["rm.sod.mage.frost.warcrafttavern.Name"] = "냉기, 화염 룬 (SoD, Warcraft Tavern)"
L["rm.sod.mage.frost.warcrafttavern.Description"] = "화염 룬을 쓰는 Warcraft Tavern의 4단계 냉기 빌드로, 추천 디스커버리 시즌 냉기 기본 제공 로테이션의 대안이며 기본적으로 꺼져 있습니다: 이것을 켜고 그것을 끄거나, 이것의 우선순위를 높이세요. 불덩이 작열로 시작; 몰아치는 열기에 불덩이 작열; 살아있는 폭탄 유지; 불태우기 연마가 있으면 불태우기로 5중첩; 재앙불꽃 화살은 두뇌 빙결 발동 시에만, 재앙불꽃 4중첩 이상에서는 절대 사용하지 않음; 빈틈은 얼음불꽃 화살. 이동 중에는 살아있는 폭탄과 화염 작렬; 무리에는 살아있는 폭탄, 냉기 돌풍, 눈보라. 알림: 과열과 함께 화염 작렬, 얼음 핏줄 중 얼어붙은 구슬, 얼음 핏줄, 한파와 그 밖의 마법사 알림."
L["rm.sod.mage.healer.Name"] = "치유 전담 (SoD)"
L["rm.sod.mage.healer.Description"] = "디스커버리 시즌 마법사 치유 로테이션으로, 재생력이나 대규모 재생력을 새겼을 때 선택됩니다. 우호적 대상이 있으면: 생명력 절반 미만에서 시간 되돌리기와 시간의 보존, 내 시간의 봉화가 없으면 재생력, 대규모 재생력, 시간 변칙. 적 대상이 있으면 내 봉화를 치유하는 피해 기술: 냉기 치유 전담은 비전냉기 화살, 그 외에는 화살 탄막에 신비한 화살, 비전 작렬 2중첩에서 비전 탄막, 안전할 때 재앙불꽃 화살(재앙불꽃 4중첩 이상에서는 절대 사용하지 않음), 비전 작렬. 알림: 신비의 마법 강화, 냉정, 얼어붙은 구슬과 그 밖의 마법사 알림. 기본적으로 꺼져 있음: 무리에 신비한 폭발, 냉기 치유 전담의 얼음창과 동결. 대규모 재생력을 정신 집중하는 동안에는 다음 주문이 이미 표시되므로 바로 취소할 수 있습니다(직접 치유량은 적습니다). 누구를 치유할지는 직접 판단합니다."
L["rm.tbc.mage.arcane.Name"] = "비전"
L["rm.tbc.mage.arcane.Description"] = "비전이 주 특성 트리일 때 선택되는 비전 로테이션입니다. 64레벨 전: 신비한 화살, 마나가 부족하면 얼음 화살. 64레벨부터: 마나를 쏟아붓는 동안(신비의 마법 강화, 피의 욕망 또는 마나 35% 이상) 비전 작렬, 그 외에는 비전 작렬 3중첩을 쌓고 중첩이 사라지기 직전까지 얼음 화살을 사용합니다. 적이 셋 이상이면 신비한 폭발과 냉기 돌풍. 알림에는 신비의 마법 강화, 냉정, 마나 보석, 환기가 포함됩니다."
L["rm.tbc.mage.fire.icyveins.Name"] = "화염 (Icy Veins)"
L["rm.tbc.mage.fire.icyveins.Description"] = "Icy Veins 기준 화염 로테이션으로, 화염이 주 특성 트리일 때 선택됩니다. 불덩이 작렬을 배우면 이것으로 전투를 시작하고, 불태우기 연마로 화염 저항력 약화 5중첩을 유지하며, 화염구가 기본 주문이고, 화염 작렬은 이동 중에 사용합니다. 적이 셋 이상이면 화염 폭풍, 용의 숨결, 불기둥을 사용합니다. 알림: 타오르는 갑옷, 마법사 갑옷 또는 얼음 갑옷, 대상 생명력 20% 미만에서 발화, 마나 보석, 환기, 그리고 마법사 공용 유틸리티."
L["rm.tbc.mage.fire.wowhead.Name"] = "화염 (Wowhead)"
L["rm.tbc.mage.fire.wowhead.Description"] = "Wowhead와 시뮬레이터 기준 화염 로테이션입니다. Icy Veins 화염 기본 제공 로테이션과 같지만, 가만히 서 있을 때 화염 작렬이 준비되면 언제든 끼워 넣고(피해 증가, 마나 소모 증가) 불덩이 작렬 대신 화염구로 시작합니다. 추천 Icy Veins 화염 기본 제공 로테이션의 대안이며 기본적으로 꺼져 있습니다: 이것을 켜고 그것을 끄거나, 이것의 우선순위를 높이세요."
L["rm.tbc.mage.frost.Name"] = "냉기"
L["rm.tbc.mage.frost.Description"] = "1레벨부터 70레벨까지의 냉기 로테이션이며, 특성을 찍기 전 마법사의 기본값입니다. 얼음 화살(4레벨 전에는 화염구), 무언가가 때리면 얼음 회오리, 교전 중인 적이 셋 이상이면 냉기 돌풍과 눈보라 또는 신비한 폭발, 얼어붙은 대상과 이동 중에는 얼음창, 마나가 떨어지면 마법봉을 사용합니다. 알림: 갑옷, 신비한 지능, 마나 보석, 환기, 마법 차단, 마법 훔치기, 얼음 보호막, 얼음 핏줄, 매서운 한파, 물의 정령. 점멸, 얼음 방패, 카이팅, 대상 선택은 직접 판단합니다."
